source('/home/jinshengxi/bladder_metabolism/results/llps_C5_cellchat_visualization_v3/scripts/common.R');STAGE<-'04_pathway_LR.R';startstage()
pw<-r('tables/C5_pathway_t20.csv.gz')[stratification=='tumor_only'&partner%in%TME];lrall<-r('tables/C5_LR_t20.csv.gz');lr<-lrall[stratification=='tumor_only'&partner%in%TME];db<-r('00_input_audit/DB_components.csv');lr<-merge(lr,db[,.(feature,ligand_genes,receptor_genes)],by='feature',all.x=TRUE)
candidate_pw<-c('COLLAGEN','LAMININ','FN1','THBS','PERIOSTIN','TENASCIN','MK','CALCR','SEMA3','WNT','VEGF','ANGPTL','PDGF','SPP1','TGFb');audit<-data.table(requested=candidate_pw,in_DB=candidate_pw%in%db$pathway_name);audit[,actual_category:=vapply(requested,function(s)paste(unique(db[pathway_name==s,annotation]),collapse=';'),character(1))];w(audit,'00_input_audit/pathway_candidate_audit.csv')
rank<-pw[,.(positive=max(positive_patients),cohorts=max(positive_datasets),median=max(patient_condition_median,na.rm=TRUE)),by=feature][order(-cohorts,-positive,-median,feature)];top<-head(rank[positive>=3,feature],15);w(rank,'tables/pathway_display_ranking.csv');lim<-c(0,max(pw[feature%in%top,patient_condition_median],na.rm=TRUE))
for(dir in c('outgoing','incoming')){z<-pw[direction==dir&feature%in%top];p<-heat(z,'partner','feature','patient_condition_median',TME,top,lim)+scale_x_discrete(labels=nice(TME));expfig(p,'04_pathway_heatmap',paste0('C5_',dir,'_pathway_top15'),z,10,8,purpose='Shared top15 pathway order and color scale',limitation='Selection by cross-dataset support, positive patients, then strength; not P values')}
endo<-pw[partner=='Endothelial'];ep<-endo[,.(positive=max(positive_patients),cohorts=max(positive_datasets),median=max(patient_condition_median,na.rm=TRUE)),by=feature][order(-cohorts,-positive,-median)];et<-head(ep[positive>=3,feature],15)
sets<-list(candidate=intersect(candidate_pw,pw$feature),compact=et);allp<-ep[positive>0|feature%in%candidate_pw,feature];for(j in seq_len(ceiling(length(allp)/35)))sets[[paste0('full_page',j)]]<-allp[seq.int((j-1)*35+1,min(j*35,length(allp)))]
for(nm in names(sets)){fs<-sets[[nm]];z<-endo[feature%in%fs];p<-heat(z,'direction','feature','patient_condition_median',c('outgoing','incoming'),fs,c(0,max(endo$patient_condition_median,na.rm=TRUE)));expfig(p,'04_pathway_heatmap',paste0('C5_Endothelial_pathway_',nm),z,7,max(5,length(fs)*.25+2),role=if(nm=='compact')'Main figure candidates'else'Supplementary figures',purpose='Endothelial bidirectional pathways; full pages preserve weak and zero candidates')}
cs<-r('tables/category_summary.csv')[partner%in%TME];for(scope in c('TME','Endothelial'))for(kind in c('absolute','relative')){z<-if(scope=='TME')copy(cs)else cs[partner=='Endothelial'];z[,edge:=paste(nice(partner),direction,sep=' | ')];val<-if(kind=='absolute')'median_strength'else'mean_fraction';p<-ggplot(z,aes(edge,.data[[val]],fill=category))+geom_col(position=if(kind=='absolute')position_dodge(.8)else'stack',width=.75);if(kind=='relative'){p<-ggplot(z,aes(edge,mean_fraction,fill=category))+geom_col(width=.75)+scale_y_continuous(labels=scales::label_percent())};p<-p+jin_theme()+theme(axis.text.x=element_text(angle=55,hjust=1))+labs(x=NULL,y=if(kind=='absolute')'Patient median category strength'else'Mean patient category fraction',fill='Communication category');expfig(p,'04_pathway_heatmap',paste0('category_',scope,'_',kind),z,if(scope=='TME')13 else 8,6,purpose='Category strengths or patient-first composition',limitation='Fractions computed per specimen, median within patient-condition, then mean; zero-total fraction=NA; independent category medians need not sum to total median')}
# Verify all requested individual axes in the formal v2 database, including absent candidates.
out<-c('COL1A1_ITGA1_ITGB1','COL1A2_ITGA1_ITGB1','COL6A2_ITGA1_ITGB1','COL6A3_ITGA1_ITGB1','FN1_ITGA5_ITGB1','POSTN_ITGAV_ITGB3','POSTN_ITGAV_ITGB5','MDK_ITGA6_ITGB1','ADM_CALCRL','SEMA3C_PLXND1','SEMA3C_NRP1_PLXNA2','WNT2_FZD4_LRP6','HSPG2_DAG1',db[ligand=='VEGFA',feature]);inc<-c('PDGFB_PDGFRB','PDGFB_PDGFRA','PDGFD_PDGFRB','COL4A1_ITGA11_ITGB1','COL4A2_ITGA11_ITGB1');req<-rbind(data.table(direction='outgoing',partner='Endothelial',feature=out),data.table(direction='incoming',partner='Endothelial',feature=inc),data.table(direction='outgoing',partner='Epithelial',feature=c('FN1_SDC1','WNT5A_FZD6','TNFSF12_TNFRSF12A')),data.table(direction='outgoing',partner='Myeloid',feature=c('APP_CD74',db[ligand=='THY1',feature])),data.table(direction='incoming',partner='Myeloid',feature=db[ligand=='SPP1',feature]),data.table(direction='incoming',partner='T_NK',feature=db[ligand=='IFNG',feature]))
for(dir in c('outgoing','incoming')){u<-lr[partner=='T_NK'&direction==dir&pathway%in%c('COLLAGEN','FN1')][order(-positive_patients,-patient_condition_median)];req<-rbind(req,u[seq_len(min(8,.N)),.(direction,partner,feature)])};req<-unique(req);audit<-merge(req,lr,by=c('feature','direction','partner'),all.x=TRUE);audit[,in_DB:=feature%in%db$feature];audit[,status:=ifelse(!in_DB,'NOT_IN_DB',ifelse(eligible_patients==0,'INELIGIBLE',ifelse(positive_patients==0,'ELIGIBLE_NOT_DETECTED','DETECTED')))];w(audit,'tables/hypothesis_LR_audit.csv')
bubble<-function(z,name,fs=NULL,role='Main figure candidates',purpose='Data-driven LR display'){
 if(!nrow(z))return();z<-copy(z);if(is.null(fs))fs<-unique(z$feature);z[,axis:=paste0(ligand_genes,' -> ',gsub(';',' + ',receptor_genes,fixed=TRUE),' [',feature,']')];z[,axis:=factor(axis,levels=rev(unique(z[match(fs,feature,nomatch=0),axis])))];z[,edge:=paste(nice(partner),direction,sep=' | ')];z[,support:=paste0(positive_patients,'/',eligible_patients)];p<-ggplot(z,aes(edge,axis,color=patient_condition_median,size=patient_prevalence))+geom_point()+geom_text(aes(label=support),nudge_x=.23,size=2.6,color='black',family='Arial',show.legend=FALSE)+scale_size_area(max_size=7,limits=c(0,1),breaks=c(0,.25,.5,.75,1),labels=scales::label_percent(),name='Patient prevalence')+scale_color_viridis_c(na.value='grey70',guide=cb(),name='Patient median strength')+scale_x_discrete(expand=expansion(add=c(.6,.9)))+jin_theme()+theme(axis.text.x=element_text(angle=35,hjust=1))+labs(x=NULL,y=NULL);expfig(p,'05_LR_bubble',name,z,if(uniqueN(z$edge)>2)16 else 12,max(5,uniqueN(z$axis)*.3+2),role=role,purpose=purpose,limitation='Area=prevalence, text=positive/eligible independent patients; not significance. Zero median can coexist with positive prevalence; receptor subunits explicit')
}
selection<-list();for(dir in c('outgoing','incoming')){d<-lr[direction==dir];rr<-d[,.(patients=max(positive_patients),cohorts=max(positive_datasets),strength=max(patient_condition_median,na.rm=TRUE)),by=feature][order(-cohorts,-patients,-strength,feature)];fs<-head(rr[patients>=3,feature],20);selection[[dir]]<-fs;bubble(d[feature%in%fs],paste0('C5_',dir,'_data_driven'),fs)
 e<-d[partner=='Endothelial'][order(-positive_datasets,-positive_patients,-patient_condition_median,feature)];ef<-head(e[positive_patients>=3,feature],20);bubble(e[feature%in%ef],paste0('C5_Endothelial_',dir,'_data_driven'),ef)
 q<-audit[direction==dir&in_DB==TRUE];bubble(q,paste0('C5_',dir,'_hypothesis'),unique(q$feature),'Supplementary figures','Prespecified hypothesis axes, including non-detections');ee<-q[partner=='Endothelial'];bubble(ee,paste0('C5_Endothelial_',dir,'_hypothesis'),unique(ee$feature),'Supplementary figures','Requested Endothelial axes')
}
ee<-audit[partner=='Endothelial'&in_DB==TRUE];bubble(ee,'C5_Endothelial_bidirectional_hypothesis',unique(ee$feature),'Supplementary figures','Outgoing and incoming requested axes; only the specified direction is evaluated per row')
# Sensitivity preserves original patient denominators; shared upstream probabilities are not independent validation.
all<-rbindlist(lapply(c(10,20,30),function(t)r(paste0('tables/C5_LR_t',t,'.csv.gz'))));sel<-unique(req[partner=='Endothelial',.(feature,direction,partner)]);ss<-merge(all,sel,by=c('feature','direction','partner'));w(ss,'tables/Endothelial_core_LR_all_thresholds.csv.gz');s<-ss[stratification=='tumor_only'];s[,label:=paste(direction,feature,sep=' | ')];p<-ggplot(s,aes(factor(min_cells),label,fill=patient_prevalence))+geom_tile(color='white',linewidth=.4)+geom_text(aes(label=paste0(positive_patients,'/',eligible_patients)),size=3,family='Arial')+scale_fill_viridis_c(limits=c(0,1),na.value='grey80',guide=cb(),name='Patient prevalence')+jin_theme()+labs(x='min.cells',y=NULL);expfig(p,'09_sensitivity_analysis','Endothelial_LR_threshold_support',s,12,max(6,uniqueN(s$label)*.27+2),role='Supplementary figures',threshold='10;20;30',purpose='Composition sensitivity, not independent repeats')
d<-ss[min_cells==20&stratification=='tumor_dataset'&stratum%in%c('GSE222315','InhouseData')];d[,label:=paste(direction,feature,sep=' | ')];for(value in c('patient_prevalence','patient_condition_median')){p<-heat(d,'stratum','label',value,c('GSE222315','InhouseData'),unique(d$label),fillname=if(value=='patient_prevalence')'Patient prevalence'else'Patient median strength');p<-p+geom_text(aes(label=paste0(positive_patients,'/',eligible_patients)),size=2.8,color='white');expfig(p,'09_sensitivity_analysis',paste0('Endothelial_LR_dataset_',value),d,12,max(6,uniqueN(d$label)*.27+2),role='Supplementary figures',purpose='Cohort-specific support and intensity',limitation='Dataset and clinical stage composition differ; no pooled-only ranking')}
cov<-rbindlist(lapply(c(10,20,30),function(t){a<-fread(file.path(TD(t),'C5_total_strength.csv'))[clinical_group!='Normal'&direction=='outgoing'];data.table(min_cells=t,specimens=uniqueN(a[!is.na(strength),specimen_id]),patients=uniqueN(a[!is.na(strength),patient_id]))}));w(cov,'tables/tumor_C5_threshold_coverage.csv');d<-melt(cov,id.vars='min_cells',variable.name='unit',value.name='n');p<-ggplot(d,aes(factor(min_cells),n,fill=unit))+geom_col(position='dodge')+geom_text(aes(label=n),position=position_dodge(.9),vjust=-.4,family='Arial',size=4)+scale_y_continuous(expand=expansion(mult=c(0,.1)))+jin_theme()+labs(x='min.cells',y='Eligible C5 specimens / patients',fill='Unit');expfig(p,'09_sensitivity_analysis','C5_threshold_coverage',d,7,5,role='Supplementary figures',threshold='10;20;30',purpose='Tumor-only C5 coverage')
